    except httpx.HTTPError as exc:
        err.print(f"API at {api_url} is not reachable. Check MC_API_URL. ({exc})", soft_wrap=True)
        raise typer.Exit(1) from None
    if response.status_code >= 400:
        err.print(error_message(response), soft_wrap=True)
        raise typer.Exit(1)
    return response
EOF

